struct MinStack {
    private var items: [(value: Int, min: Int)] = []
    mutating func push(_ v: Int) { items.append((v, min(v, items.last?.min ?? v))) }
    mutating func pop() { items.removeLast() }
    func top() -> Int { items.last!.value }
    func getMin() -> Int { items.last!.min }
}
